# [derive (Debug)] enum NodeOrNull < T > { Node (Node < T >) , Null } # [derive (Debug)] struct Node < T > { value : T , lower_equal : NodeOrNull < T > , higher : NodeOrNull < T > } impl < T > Node < T > { fn new (val : T) -> Self { return Node { value : val , higher : NodeOrNull :: Null , lower_equal : NodeOrNull :: Null } ; } } # [derive (Debug)] struct Sort < T > { root : NodeOrNull < T > } impl < T > Sort < T > { fn new () -> Self { return Sort { root : NodeOrNull :: Null } ; } fn of (val : Node < T >) -> Self { return Sort { root : val } ; } } fn main () { let root = Node :: new (5) ; let sort = Sort :: of (root) ; println ! ("{:#?}" , sort) ; }